      "primarySkill": "employment_classification",
      "secondarySkills": [
        "discouraged_workers"
      ],
      "repairSkill": "employment_classification",
      "commonError": "Classifying people by desire for work instead of paid work and active search status.",
      "q": "A survey has 84 adults working for pay, including 14 seeking more hours; 6 available jobless adults applied last week; 30 jobless adults are not searching. Which official count and limitation are correct?",
      "options": [
        "Labor force 90 and unemployment about 6.7%; underemployment among paid workers is not in that rate",
        "Labor force 104 and unemployment about 19.2%; add those seeking more hours to unemployment",
        "Labor force 120 and unemployment 5%; use every adult in the denominator",
        "Labor force 76 and unemployment about 7.9%; exclude part-time paid workers"
      ],
      "tag": "employment_categories",
      "type": "multi-step",
      "objective": "LO29.2",
      "feedback": "All 84 paid workers are employed, including those wanting more hours. Add the 6 active, available seekers for LF = 90; 6/90 ≈ 6.7%. The rate does not measure all of the part-time workers’ unmet demand for hours.",
      "aHash": "34ef5ef4e16035a96d5ec6ff24b2a779a6b60ca060ae35909d188dc7d917b733",
